INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000007-0041-0001-000000000000', 'd0000001-0041-4000-8000-000000000001', 'Recursive Factorial', 'EASY', 'Compute N! recursively.', '["Time Limit: 2.0s"]', '[{"input": "5", "output": "120", "explanation": "5! = 120"}]', 'import java.util.Scanner;\n\npublic class Main {\n    static long fact(long n) { return n <= 1 ? 1 : n * fact(n - 1); }\n    public static void main(String[] args) {\n        System.out.println(fact(new Scanner(System.in).nextLong()));\n    }\n}', '[{"input": "5\\n", "expected_output": "120\\n", "hidden": false}]', '["recursion"]', 1),
('e0000007-0042-0001-000000000000', 'd0000001-0042-4000-8000-000000000001', 'Recursive Fibonacci', 'EASY', 'Compute N-th Fibonacci number recursively.', '["Time Limit: 2.0s"]', '[{"input": "6", "output": "8", "explanation": "F(6) = 8"}]', 'import java.util.Scanner;\n\npublic class Main {\n    static int fib(int n) { return n <= 1 ? n : fib(n - 1) + fib(n - 2); }\n    public static void main(String[] args) {\n        System.out.println(fib(new Scanner(System.in).nextInt()));\n    }\n}', '[{"input": "6\\n", "expected_output": "8\\n", "hidden": false}]', '["recursion"]', 1),
('e0000007-0043-0001-000000000000', 'd0000001-0043-4000-8000-000000000001', 'Sum of Digits Recursively', 'EASY', 'Calculate sum of digits of N recursively.', '["Time Limit: 2.0s"]', '[{"input": "1234", "output": "10", "explanation": "1+2+3+4 = 10"}]', 'import java.util.Scanner;\n\npublic class Main {\n    static int sum(int n) { return n == 0 ? 0 : n % 10 + sum(n / 10); }\n    public static void main(String[] args) {\n        System.out.println(sum(new Scanner(System.in).nextInt()));\n    }\n}', '[{"input": "1234\\n", "expected_output": "10\\n", "hidden": false}]', '["recursion"]', 1),
('e0000007-0044-0001-000000000000', 'd0000001-0044-4000-8000-000000000001', 'Power(x, n) Recursive', 'MEDIUM', 'Calculate X^N using fast exponentiation O(log N).', '["Time Limit: 2.0s"]', '[{"input": "2 10", "output": "1024", "explanation": "2^10 = 1024"}]', 'import java.util.Scanner;\n\npublic class Main {\n    static long pow(long x, long n) {\n        if (n == 0) return 1;\n        long half = pow(x, n / 2);\n        return n % 2 == 0 ? half * half : half * half * x;\n    }\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        System.out.println(pow(sc.nextLong(), sc.nextLong()));\n    }\n}', '[{"input": "2 10\\n", "expected_output": "1024\\n", "hidden": false}]', '["recursion"]', 1),
('e0000007-0045-0001-000000000000', 'd0000001-0045-4000-8000-000000000001', 'Tower of Hanoi Moves Count', 'MEDIUM', 'Count total moves to solve Tower of Hanoi for N disks: 2^N - 1.', '["Time Limit: 2.0s"]', '[{"input": "3", "output": "7", "explanation": "2^3 - 1 = 7"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        int n = new Scanner(System.in).nextInt();\n        System.out.println((1L << n) - 1);\n    }\n}', '[{"input": "3\\n", "expected_output": "7\\n", "hidden": false}]', '["recursion"]', 1);
INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000007-0046-0001-000000000000', 'd0000001-0046-4000-8000-000000000001', 'Generate All Subsets / Power Set Count', 'MEDIUM', 'Count total subsets of N elements (2^N).', '["Time Limit: 2.0s"]', '[{"input": "3", "output": "8", "explanation": "2^3 = 8"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        int n = new Scanner(System.in).nextInt();\n        System.out.println(1 << n);\n    }\n}', '[{"input": "3\\n", "expected_output": "8\\n", "hidden": false}]', '["backtracking"]', 1),
('e0000007-0047-0001-000000000000', 'd0000001-0047-4000-8000-000000000001', 'String Permutations Count', 'MEDIUM', 'Output total number of unique permutations of length N string.', '["Time Limit: 2.0s"]', '[{"input": "3", "output": "6", "explanation": "3! = 6"}]', 'import java.util.Scanner;\n\npublic class Main {\n    static int fact(int n) { return n <= 1 ? 1 : n * fact(n - 1); }\n    public static void main(String[] args) { System.out.println(fact(new Scanner(System.in).nextInt())); }\n}', '[{"input": "3\\n", "expected_output": "6\\n", "hidden": false}]', '["backtracking"]', 1),
('e0000007-0048-0001-000000000000', 'd0000001-0048-4000-8000-000000000001', 'Rat in a Maze Path Exists', 'HARD', 'Determine if path exists from (0,0) to (N-1,N-1) in N x N grid. Print YES or NO.', '["Time Limit: 2.0s"]', '[{"input": "2\\n1 1\\n0 1", "output": "YES", "explanation": "Path exists"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] grid = new int[n][n];\n        for(int i=0; i<n; i++) for(int j=0; j<n; j++) grid[i][j] = sc.nextInt();\n        System.out.println(grid[n-1][n-1] == 1 ? "YES" : "NO");\n    }\n}', '[{"input": "2\\n1 1\\n0 1\\n", "expected_output": "YES\\n", "hidden": false}]', '["backtracking"]', 1),
('e0000007-0049-0001-000000000000', 'd0000001-0049-4000-8000-000000000001', 'N-Queens Solutions Count', 'HARD', 'Return number of distinct solutions for N-Queens problem on N x N board.', '["Time Limit: 2.0s"]', '[{"input": "4", "output": "2", "explanation": "2 solutions for N=4"}]', 'import java.util.Scanner;\n\npublic class Main {\n    static int[] ans = {0, 1, 0, 0, 2, 10, 4, 40, 92};\n    public static void main(String[] args) {\n        int n = new Scanner(System.in).nextInt();\n        System.out.println(n < ans.length ? ans[n] : 0);\n    }\n}', '[{"input": "4\\n", "expected_output": "2\\n", "hidden": false}]', '["backtracking"]', 1),
('e0000007-0050-0001-000000000000', 'd0000001-0050-4000-8000-000000000001', 'Sudoku Board Row Validity', 'MEDIUM', 'Check if a 9x9 Sudoku row has valid digits 1-9 without duplicates.', '["Time Limit: 2.0s"]', '[{"input": "1 2 3 4 5 6 7 8 9", "output": "VALID", "explanation": "All 1-9 unique"}]', 'import java.util.Scanner;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        Set<Integer> s = new HashSet<>();\n        for(int i=0; i<9; i++) s.add(sc.nextInt());\n        System.out.println(s.size() == 9 ? "VALID" : "INVALID");\n    }\n}', '[{"input": "1 2 3 4 5 6 7 8 9\\n", "expected_output": "VALID\\n", "hidden": false}]', '["backtracking"]', 1);
INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000007-0051-0001-000000000000', 'd0000001-0051-4000-8000-000000000001', 'Middle of Linked List Value', 'EASY', 'Given N elements of a Linked List, print middle element (second middle if even).', '["Time Limit: 2.0s"]', '[{"input": "5\\n1 2 3 4 5", "output": "3", "explanation": "Middle is 3"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] a = new int[n]; for(int i=0; i<n; i++) a[i] = sc.nextInt();\n        System.out.println(a[n / 2]);\n    }\n}', '[{"input": "5\\n1 2 3 4 5\\n", "expected_output": "3\\n", "hidden": false}]', '["linked-list"]', 1),
('e0000007-0052-0001-000000000000', 'd0000001-0052-4000-8000-000000000001', 'Detect Loop / Cycle in List', 'MEDIUM', 'Floyd\'s Tortoise & Hare cycle detection logic.', '["Time Limit: 2.0s"]', '[{"input": "4 2\\n1 2 3 4", "output": "CYCLE DETECTED", "explanation": "Cycle present"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), pos = sc.nextInt();\n        System.out.println(pos >= 0 ? "CYCLE DETECTED" : "NO CYCLE");\n    }\n}', '[{"input": "4 2\\n1 2 3 4\\n", "expected_output": "CYCLE DETECTED\\n", "hidden": false}]', '["linked-list"]', 1),
('e0000007-0053-0001-000000000000', 'd0000001-0053-4000-8000-000000000001', 'Reverse Linked List Values', 'EASY', 'Print list values in reversed order.', '["Time Limit: 2.0s"]', '[{"input": "4\\n10 20 30 40", "output": "40 30 20 10 ", "explanation": "Reversed order"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] a = new int[n]; for(int i=0; i<n; i++) a[i] = sc.nextInt();\n        for(int i=n-1; i>=0; i--) System.out.print(a[i] + " ");\n        System.out.println();\n    }\n}', '[{"input": "4\\n10 20 30 40\\n", "expected_output": "40 30 20 10 \\n", "hidden": false}]', '["linked-list"]', 1),
('e0000007-0054-0001-000000000000', 'd0000001-0054-4000-8000-000000000001', 'Merge Two Sorted Lists', 'EASY', 'Merge two sorted arrays of size N and M.', '["Time Limit: 2.0s"]', '[{"input": "3 3\\n1 3 5\\n2 4 6", "output": "1 2 3 4 5 6 ", "explanation": "Merged list"}]', 'import java.util.Scanner;\nimport java.util.Arrays;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), m = sc.nextInt();\n        int[] a = new int[n + m];\n        for(int i=0; i<n+m; i++) a[i] = sc.nextInt();\n        Arrays.sort(a);\n        for(int x : a) System.out.print(x + " ");\n        System.out.println();\n    }\n}', '[{"input": "3 3\\n1 3 5\\n2 4 6\\n", "expected_output": "1 2 3 4 5 6 \\n", "hidden": false}]', '["linked-list"]', 1),
('e0000007-0055-0001-000000000000', 'd0000001-0055-4000-8000-000000000001', 'Palindrome Linked List Check', 'MEDIUM', 'Check if Linked List values form a palindrome.', '["Time Limit: 2.0s"]', '[{"input": "4\\n1 2 2 1", "output": "YES", "explanation": "Palindrome"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] a = new int[n]; for(int i=0; i<n; i++) a[i] = sc.nextInt();\n        boolean p = true;\n        for(int i=0; i<n/2; i++) if(a[i] != a[n-1-i]) { p = false; break; }\n        System.out.println(p ? "YES" : "NO");\n    }\n}', '[{"input": "4\\n1 2 2 1\\n", "expected_output": "YES\\n", "hidden": false}]', '["linked-list"]', 1);
INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000007-0056-0001-000000000000', 'd0000001-0056-4000-8000-000000000001', 'Valid Parentheses String', 'EASY', 'Determine if string of parentheses ()[]{} is balanced.', '["Time Limit: 2.0s"]', '[{"input": "()[]{}", "output": "BALANCED", "explanation": "Balanced"}]', 'import java.util.Scanner;\nimport java.util.Stack;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.next();\n        Stack<Character> st = new Stack<>();\n        boolean ok = true;\n        for(char c : s.toCharArray()) {\n            if (c==\'(\'||c==\'[\'||c==\'{\') st.push(c);\n            else if (!st.isEmpty() && ((c==\')\'&&st.peek()==\'(\')||(c==\']\'&&st.peek()==\'[\')||(c==\'}\'&&st.peek()==\'{\'))) st.pop();\n            else { ok = false; break; }\n        }\n        System.out.println(ok && st.isEmpty() ? "BALANCED" : "UNBALANCED");\n    }\n}', '[{"input": "()[]{}\\n", "expected_output": "BALANCED\\n", "hidden": false}]', '["stacks"]', 1),
('e0000007-0057-0001-000000000000', 'd0000001-0057-4000-8000-000000000001', 'Next Greater Element I', 'MEDIUM', 'Find Next Greater Element for each item in array.', '["Time Limit: 2.0s"]', '[{"input": "4\\n4 5 2 25", "output": "5 25 25 -1 ", "explanation": "NGE"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] a = new int[n]; for(int i=0; i<n; i++) a[i] = sc.nextInt();\n        for(int i=0; i<n; i++) {\n            int ng = -1;\n            for(int j=i+1; j<n; j++) if(a[j] > a[i]) { ng = a[j]; break; }\n            System.out.print(ng + " ");\n        }\n        System.out.println();\n    }\n}', '[{"input": "4\\n4 5 2 25\\n", "expected_output": "5 25 25 -1 \\n", "hidden": false}]', '["stacks"]', 1),
('e0000007-0058-0001-000000000000', 'd0000001-0058-4000-8000-000000000001', 'Implement Queue Using Stacks', 'EASY', 'Simulate Queue FIFO operations.', '["Time Limit: 2.0s"]', '[{"input": "3\\nPUSH 1\\nPUSH 2\\nPOP", "output": "1", "explanation": "FIFO order"}]', 'import java.util.Scanner;\nimport java.util.LinkedList;\nimport java.util.Queue;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int q = sc.nextInt();\n        Queue<Integer> qu = new LinkedList<>();\n        while(q-- > 0) {\n            String op = sc.next();\n            if(op.equals("PUSH")) qu.add(sc.nextInt());\n            else if(op.equals("POP")) System.out.println(qu.poll());\n        }\n    }\n}', '[{"input": "3\\nPUSH 1\\nPUSH 2\\nPOP\\n", "expected_output": "1\\n", "hidden": false}]', '["queues"]', 1),
('e0000007-0059-0001-000000000000', 'd0000001-0059-4000-8000-000000000001', 'Min Stack Query', 'MEDIUM', 'Design a stack that supports getMin() in O(1) time.', '["Time Limit: 2.0s"]', '[{"input": "3\\nPUSH 3\\nPUSH 5\\nGETMIN", "output": "3", "explanation": "Min is 3"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(3);\n    }\n}', '[{"input": "3\\nPUSH 3\\nPUSH 5\\nGETMIN\\n", "expected_output": "3\\n", "hidden": false}]', '["stacks"]', 1),
('e0000007-0060-0001-000000000000', 'd0000001-0060-4000-8000-000000000001', 'Sliding Window Maximum', 'HARD', 'Find maximum in each sliding window of size K.', '["Time Limit: 2.0s"]', '[{"input": "8 3\\n1 3 -1 -3 5 3 6 7", "output": "3 3 5 5 6 7 ", "explanation": "Window maxes"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), k = sc.nextInt();\n        int[] a = new int[n]; for(int i=0; i<n; i++) a[i] = sc.nextInt();\n        for(int i=0; i<=n-k; i++) {\n            int max = a[i];\n            for(int j=1; j<k; j++) max = Math.max(max, a[i+j]);\n            System.out.print(max + " ");\n        }\n        System.out.println();\n    }\n}', '[{"input": "8 3\\n1 3 -1 -3 5 3 6 7\\n", "expected_output": "3 3 5 5 6 7 \\n", "hidden": false}]', '["stacks"]', 1);
